/**
 * Writes data/library/definitions/<work>.json and data/library/quickref/<work>.json.
 *
 * WHY THIS IS A NODE SCRIPT AND NOT A PYTHON ONE, like every other generator in
 * this repository: the definitions parser and the quick-reference extractor
 * must ALSO run in the browser, over a document the reader added themselves
 * (`src/lib/library/personal.ts`). A Python copy and a TypeScript copy of the
 * same grammar is two implementations of one thing, and the one that is not
 * exercised by `pnpm test` is the one that drifts. So the committed datasets are
 * generated by the very modules the app ships — `src/lib/library/definitions.ts`
 * and `src/lib/library/quickref.ts` — loaded through Vite's own SSR module
 * runner, which resolves this project's `@/` aliases and compiles its
 * TypeScript exactly as the build does. No new dependency: Vite is already here.
 *
 *   node scripts/library-extracts.mjs           # write
 *   node scripts/library-extracts.mjs --check   # rebuild and compare, write nothing
 *
 * Hand-run and on no cron, for the reason `pay_matrix.py` and `drafting_seed.py`
 * are: these files change when the corpus underneath them changes, and that is
 * a reading job with a pull request, not a schedule.
 */

import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import process from 'node:process'

import { createServer } from 'vite'

const ROOT = process.cwd()
const VERSION = '1.0.0'
const STAMP = new Date().toISOString().slice(0, 10)

const readJson = (...parts) => JSON.parse(readFileSync(resolve(ROOT, ...parts), 'utf8'))

/**
 * Works whose definitions clause exists and cannot be read, with the reason.
 *
 * A clause that yields no term is normally a broken grammar, so it fails the
 * run. This one is a broken SOURCE: the extracted text of CCS (Pension) rule 3
 * has lost its clause letters and its quotation marks outright — it reads "(a
 * Department or Office of the Central Government … ns average emoluments as
 * determined in accordance with rule 32" — so there is nothing there for any
 * grammar to find. Recorded rather than silently tolerated, and an entry here
 * is a claim that somebody looked. docs/DATA-GAPS.md #72.
 */
const UNPARSEABLE = {
  'ccs-pension':
    'the extracted text of rule 3 has lost its clause markers and quoted terms (docs/DATA-GAPS.md #72)',
}

/** The same formatting `scripts/ingest/ingest_common.py#write_json` produces. */
function writeJson(path, payload, check) {
  const text = `${JSON.stringify(payload, null, 2)}\n`
  const encoded = Buffer.from(text, 'utf8')
  const full = resolve(ROOT, path)
  const same = existsSync(full) && Buffer.compare(readFileSync(full), encoded) === 0
  if (!check && !same) {
    mkdirSync(dirname(full), { recursive: true })
    writeFileSync(full, encoded)
  }
  return { changed: !same, sha: createHash('sha256').update(encoded).digest('hex') }
}

/**
 * `generatedAt` moves on every run whether or not the data did, so `--check`
 * masks it before comparing — the same rule `strip_volatile` states on the
 * Python side, and the reason the weekly ingest's pull request is not empty
 * noise.
 */
const withoutStamp = (value) => {
  const copy = structuredClone(value)
  delete copy.generatedAt
  return copy
}

async function main() {
  const check = process.argv.includes('--check')

  const server = await createServer({
    configFile: 'vite.config.ts',
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  })

  let failures = 0
  const note = (message) => {
    console.log(`  ! ${message}`)
    failures += 1
  }

  try {
    const { buildCorpus } = await server.ssrLoadModule('/src/lib/library/corpus.ts')
    const { isDefinitionsUnit, parseDefinitions } = await server.ssrLoadModule(
      '/src/lib/library/definitions.ts',
    )
    const { extractQuickRef } = await server.ssrLoadModule('/src/lib/library/quickref.ts')

    const index = readJson('data/library/index.json')
    let totalTerms = 0
    let totalRows = 0
    const changed = []

    for (const entry of index.works) {
      const work = readJson('data/library', entry.file)
      const corpus = buildCorpus(work, readJson('data', work.corpus.file))
      const units = work.readingOrder.map((id) => corpus.units.get(id)).filter(Boolean)

      // ------------------------------------------------------ definitions
      //
      // The clause is found by the same predicate the reader uses on a personal
      // work, and the FIRST match wins: several of these documents use the word
      // "definitions" again in a later heading ("Definitions of pay"), and the
      // one that opens the document is the one that defines its vocabulary.
      const source = units.find((unit) => isDefinitionsUnit(unit.heading.en, unit.body.en.join(' ')))
      const terms = source ? parseDefinitions(source.body.en.join(' ')) : []
      totalTerms += terms.length

      if (source && terms.length === 0 && !UNPARSEABLE[work.id]) {
        note(`${work.id}: found a definitions clause (${source.number}) and read no term out of it`)
      }

      changed.push([
        `data/library/definitions/${work.id}.json`,
        {
          $schema: '../../../schemas/library-definitions.schema.json',
          version: VERSION,
          generatedAt: STAMP,
          workId: work.id,
          // `null` rather than an omitted key: four of the fifteen works have no
          // definitions clause at all, and a consumer should read that as an
          // answer rather than as a missing field.
          unitId: source?.id ?? null,
          unitNumber: source?.number ?? null,
          source: work.source,
          terms,
        },
      ])

      // -------------------------------------------------------- quick-ref
      const rows = []
      for (const unit of units) {
        for (const row of extractQuickRef(unit.body.en.join(' '))) {
          rows.push({ unitId: unit.id, unitNumber: unit.number, ...row })
        }
      }
      totalRows += rows.length

      changed.push([
        `data/library/quickref/${work.id}.json`,
        {
          $schema: '../../../schemas/library-quickref.schema.json',
          version: VERSION,
          generatedAt: STAMP,
          workId: work.id,
          source: work.source,
          counts: {
            time: rows.filter((row) => row.kind === 'time').length,
            money: rows.filter((row) => row.kind === 'money').length,
            authority: rows.filter((row) => row.kind === 'authority').length,
          },
          rows,
        },
      ])
    }

    let wrote = 0
    for (const [path, payload] of changed) {
      const existing = existsSync(resolve(ROOT, path)) ? readJson(path) : null
      const identical =
        existing && JSON.stringify(withoutStamp(existing)) === JSON.stringify(withoutStamp(payload))
      // An unchanged dataset must be written back byte-identically, or every run
      // produces a diff of nothing but a date and nobody reads the real ones.
      const out = identical ? { ...payload, generatedAt: existing.generatedAt } : payload
      const result = writeJson(path, out, check)
      if (result.changed) {
        wrote += 1
        console.log(`${check ? 'differs' : 'wrote'} ${path}`)
      }
    }

    console.log(
      `  ${index.works.length} works, ${totalTerms} defined terms, ${totalRows} quick-reference rows`,
    )
    if (check && wrote > 0) {
      console.log(`! ${wrote} file(s) differ from disk`)
      return 1
    }
    if (check) console.log(`ok: ${changed.length} file(s) compared`)
    return failures > 0 ? 1 : 0
  } finally {
    await server.close()
  }
}

process.exitCode = await main()
